import { createAsyncThunk, createSlice } from "@reduxjs/toolkit";
import generateLedgerService from "../services/generateLedgerService";
import { uniqBy } from "lodash";

const initialState = {
  generateLedgers: [],
  isError: false,
  isSuccess: false,
  isLoading: false,
  message: "",
  next_page_param: null,
};

export const getGenerateLedger = createAsyncThunk(
  "loanOperationModule/getGenerateLedger",
  async ({ params, url, firstFetch = true }, thunkAPI) => {
    try {
      const response = await generateLedgerService.getGenerateLedger(params, url);

      const {
        metadata: { info },
      } = response;

      const remainingPages = Math.ceil(
        ((+info?.total || 0) - (+info?.offset || 0)) / +info?.limit || 10
      );

      const next_page_param =
        remainingPages >= 1
          ? {
              ...params,
              offset: (+info?.limit || 10) + (+info?.offset || 0),
            }
          : null;
      return {
        info : info,
        data: response.data,
        firstFetch,
        next_page_param,
      };
    } catch (error) {
      const message =
        (error.response &&
          error.response.data &&
          error.response.data.message) ||
        error.message ||
        error.toString();
      return thunkAPI.rejectWithValue(message);
    }
  }
);

export const generateLedgerSlice = createSlice({
  name: "loanOperationModule",
  initialState,
  reducers: {
    reset: () => initialState,
  },
  extraReducers: (builder) => {
    builder
      .addCase(getGenerateLedger.pending, (state) => {
        state.isLoading = true;
        state.next_page_param = null;
      })
      .addCase(getGenerateLedger.fulfilled, (state, action) => {
        state.isSuccess = true;
        const { firstFetch, data, next_page_param } = action.payload;
        if (firstFetch) {
          state.generateLedgers = data;
        } else {
          // state.generateLedgers = state.generateLedgers.concat(data);
          state.generateLedgers = uniqBy(state.generateLedgers.concat(data), "id");
        }

        state.next_page_param = next_page_param;
        state.isLoading = false;
      })
      .addCase(getGenerateLedger.rejected, (state, action) => {
        state.isLoading = false;
        state.isError = true;
        state.message = action.payload;
        state.next_page_param = null;
      })
  },
});

export const { reset } = generateLedgerSlice.actions;
export default generateLedgerSlice.reducer;
